import re,os,glob
chdir='blueprint/src/chapters'
sorried={'lem:sectionGradedModule_fg','lem:pullback_tensor_map_isiso','lem:gamma_fiber_baseChange_field','lem:gradedHilbert_fiber','thm:quot_representable'}
envs=('theorem','lemma','proposition','corollary','definition','remark','example','notation','convention')
# build node -> (proof_leanok, uses) over ALL chapters (to catch dependents in my slice)
nodes={}
for fn in glob.glob(chdir+'/*.tex'):
    lines=open(fn,encoding='utf-8').read().split('\n')
    i=0
    while i<len(lines):
        l=lines[i]
        m=re.search(r'\\begin\{('+'|'.join(envs)+r')\}',l) if not l.lstrip().startswith('%') else None
        if m:
            j=i;blk=[]
            while j<len(lines):
                blk.append(lines[j])
                if re.search(r'\\end\{'+m.group(1)+r'\}',lines[j]):break
                j+=1
            stmt='\n'.join(x for x in blk if not x.lstrip().startswith('%'))
            lab=re.search(r'\\label\{([^}]*)\}',stmt)
            k=j+1;pf=''
            while k<len(lines) and k<j+8:
                if '\\begin{proof}' in lines[k]:
                    pb=[]
                    while k<len(lines):
                        pb.append(lines[k])
                        if '\\end{proof}' in lines[k]:break
                        k+=1
                    pf='\n'.join(x for x in pb if not x.lstrip().startswith('%'));break
                if re.search(r'\\begin\{',lines[k]):break
                k+=1
            if lab:
                uses=set()
                for mm in re.finditer(r'\\uses\{([^}]*)\}',stmt+'\n'+pf):
                    uses|={u.strip() for u in mm.group(1).split(',') if u.strip()}
                nodes[lab.group(1)]=(os.path.basename(fn),i+1,'\\leanok' in pf,uses,'\\leanok' in stmt)
            i=j+1
        else: i+=1
# transitive closure of sorried-taint
taint=set(sorried)
changed=True
while changed:
    changed=False
    for lab,(f,ln,pfok,uses,stok) in nodes.items():
        if lab in taint: continue
        if uses & taint:
            taint.add(lab); changed=True
myfiles={"Picard_QuotScheme.tex","Picard_GrassmannianQuot.tex","Picard_FlatteningStratification.tex","Picard_SectionGradedRing.tex","Picard_LineBundleCoherence.tex","Picard_GrassmannianCells.tex"}
print("nodes in slice with proof-\\leanok but transitively depending on a sorried leaf:")
for lab in sorted(taint-sorried):
    f,ln,pfok,uses,stok=nodes[lab]
    if f in myfiles and pfok:
        print('  %-42s %s:%d  uses-taint=%s'%(lab,f,ln,sorted(uses&taint)))
print()
print("dangling \\uses (target label undefined), in slice:")
for lab,(f,ln,pfok,uses,stok) in sorted(nodes.items()):
    if f not in myfiles: continue
    d=[u for u in uses if u not in nodes]
    if d: print('  %-42s %s:%d -> %s'%(lab,f,ln,d))
